const SECRET_EGRESS_USAGE_PROMPT=`Gateway-host commands: use auto-injected opaque env sentinel under stored name. No secret templates; never override/print that variable. Native shell/sandbox/node: no protected injection. First command snapshots store for run; late saves need next turn.`;const EXEC_TOOL_DISPLAY_SUMMARY=`Run shell now.`;const PROCESS_TOOL_DISPLAY_SUMMARY=`Inspect/control exec sessions.`;const CRON_TOOL_DISPLAY_SUMMARY=`Schedule reminders, automations, wake events.`;const SESSIONS_LIST_TOOL_DISPLAY_SUMMARY=`List visible sessions; filters/previews.`;const SESSIONS_HISTORY_TOOL_DISPLAY_SUMMARY=`Read sanitized session history.`;const SESSIONS_SEARCH_TOOL_DISPLAY_SUMMARY=`Search past chats.`;const SESSIONS_SEND_TOOL_DISPLAY_SUMMARY=`Run same-Gateway session/agent.`;const SESSIONS_SEND_RESULT_GUIDANCE='Accepted results report target admission as `targetDisposition: "queued"` or `"steered"`; `delivery.status` is only later reply delivery state, and neither proves target completion.';const SESSIONS_SPAWN_TOOL_DISPLAY_SUMMARY=`Spawn hidden subagent (ephemeral) or visible work session (durable).`;const SESSIONS_SPAWN_SUBAGENT_TOOL_DISPLAY_SUMMARY=`Spawn subagent session.`;const AGENTS_WAIT_TOOL_DISPLAY_SUMMARY=`Wait for collector subagents.`;const SESSION_STATUS_TOOL_DISPLAY_SUMMARY=`Show session status/model/usage.`;const ASK_USER_TOOL_DISPLAY_SUMMARY=`Ask the user and wait for an answer.`;const SUGGEST_TASK_TOOL_DISPLAY_SUMMARY=`Suggest follow-up work for operator approval.`;const DISMISS_TASK_TOOL_DISPLAY_SUMMARY=`Withdraw a pending task suggestion.`;const SKILL_WORKSHOP_TOOL_DISPLAY_SUMMARY=`Save, improve, archive, and restore your learned skills.`;const SKILL_LIBRARY_TOOL_DISPLAY_SUMMARY=`Author skills in the personal library`;function describeAgentsListTool(e){return e?'List configured agent ids with name/model/runtime metadata, allowed as `sessions_spawn(runtime:"subagent")` targets.':`List configured agent ids with name/model/runtime metadata that can be used as subagent spawn targets.`}function describeAgentsWaitTool(e){return`Wait for ${e?`collector subagents started by sessions_spawn collect=true`:`collector subagent runs`}. Accepts many run ids; returns once any completes (completed results incl. structured output, plus pending ids), or on timeoutSeconds.`}const SESSION_VISIBILITY_SCOPE_COPY={self:`current session only`,tree:`current session + own spawn subtree; the main session sees all sessions of its agent`,agent:`all sessions of this agent`,all:`all sessions, cross-agent per tools.agentToAgent`};function describeSessionVisibilityScope(e,t){if(t?.spawnRestricted&&e===`tree`)return`current session + own spawn subtree (sandbox: spawned sessions only)`;return SESSION_VISIBILITY_SCOPE_COPY[e]}const SESSION_LINK_RULE_DESCRIPTION=`How to build Control UI URLs for sessionKey values in this result.`;function describeSessionLinkRule(e){return`When pointing the user at a session, cite its Control UI URL: main session -> \`${e}/chat/<agentId>\`; any other display session key -> \`${e}/chat/<agentId>/~key/\` + key minus \`agent:<agentId>:\`, with \`:\` replaced by \`/\`.`}function describeSessionsListTool(e){return[`List visible session metadata and groups; filter ownerId/creatorId, projectId/workspaceDir, group/pinned, kind/agent/activity/archive. relationship=owned|created|involving selects the authenticated requesting user's sessions, not the agent's owner.`,`Metadata-only by default. limit defaults to 100; larger requests stay valid but limitApplied never exceeds 200. count is this page, not an inventory total. Continue with nextOffset and identical filters while hasMore; truncationReason names a scan/byte budget. Pages are live: deduplicate by agentId/key/sessionId or restart for a fresh inventory. archived=all includes active and archived rows.`,`Preview recent messages inline via includeLastMessage/messageLimit; includeDerivedTitles adds derived titles. enrichmentOmitted means previews exceeded the byte budget; read history separately.`,`Use before history/send target selection.`,...e?.sessionLinkBase?[describeSessionLinkRule(e.sessionLinkBase)]:[]].join(` `)}function describeSessionsHistoryTool(e){return[`Read sanitized visible-session history.`,`Before reply/debug/resume. Use messageId for anchored history; sessionId selects its transcript and requires messageId. Omit both for the latest tail. offset pages unanchored history and is ignored with messageId. limit bounds either mode. Include tool messages with includeTools.`,`pendingInputs are accepted inputs outside model history; page with pendingBefore=nextBefore. Cancelled inputs never replay; interrupted means saved without an active retry. Eligible durable peer sends can regain queued custody on startup. Lower limit for richer pending previews.`,...e?.sessionLinkBase?[describeSessionLinkRule(e.sessionLinkBase)]:[]].join(` `)}function describeSessionsSearchTool(e){return[`Search visible past sessions for matching user and assistant text.`,...e?.sessionLinkBase?[describeSessionLinkRule(e.sessionLinkBase)]:[]].join(` `)}function describeSessionsSendTool(e){return[`Send a message to a permitted session on this Gateway by sessionKey/label, or a configured local agent by agentId; sessionKey wins redundant label. Explicit per-agent send destinations can permit messaging without transcript access.`,`A session identifies model context, not an external address. When a new turn starts, its reply reaches you once: inline when available, otherwise as a later inter-session input. Continue with another sessions_send; post to channels with message.`,SESSIONS_SEND_RESULT_GUIDANCE,`Omit mode to automatically continue your paused native child task; returns runId/taskRunId with task-owned completion instead of an inline wait or watch. Ordinary peer sends start a separate turn. A send to your own busy child steers its active run instead of queueing a turn for after it ends; a zero-wait send to an eligible run-scoped target may use its active input queue. An idle recipient or a default self-send starts a new turn; timeoutSeconds bounds waiting for the separately admitted turn’s reply. mode:notify queues ephemeral context for the next turn without waking or starting work (bounded process memory, not a durable inbox). mode:steer injects guidance into an active supported run and never starts idle work. mode:followup always starts a separate turn and preserves its independent reply; it does not resume a paused task. mode:resume requires a paused native child task and rejects watch:true and positive timeoutSeconds.`,`${e?.allowThreadTargets?``:`Thread chats rejected: target parent channel. `}Missing configured-agent main created. status "no_reply" is terminal, so do not wait for another reply.`,`A timeoutSeconds:0 send that starts a new turn for your existing native child gives this turn a completion to await with sessions_yield, even while queued. watch:true requires status visibility and additionally reports later target-session changes; on a steer it can claim the child's existing pending completion.`].join(` `)}function describeSubagentSpawnContext(e){return[`Native: explicit context="isolated" starts clean; context="fork" copies requester transcript and requires the same agent.`,e?`Omitted context follows configured threadBindings.defaultSpawnContext policy (fork by default) with thread=true; without a thread it is isolated.`:`Omitted context is isolated.`].join(` `)}const SESSIONS_SPAWN_COLLECTOR_GUIDANCE="Default to ordinary spawn for one or a few children unless you need in-turn result collection. Use `collect=true` (swarm) for that or large parallel fan-out (several similar children, about five or more). Collectors send no completion notification and cannot be steered; explicitly collect their results; structured result per `outputSchema`; `groupId` groups a batch.";function describeSessionsSpawnTool(e){const t=e?.sessionToolsVisibility?`Session listing/addressing obeys \`tools.sessions.visibility\` (${e.sessionToolsVisibility}: ${describeSessionVisibilityScope(e.sessionToolsVisibility,{spawnRestricted:e.spawnRestricted})}).`:`Session listing/addressing obeys \`tools.sessions.visibility\` (\`all\` default: ${describeSessionVisibilityScope(`all`)}).`;const n=e?.acpAvailable===false?'Spawn child session; default `runtime="subagent"`.':'Spawn child session; default `runtime="subagent"`; ACP needs explicit `runtime="acp"`.';const r=e?.agentIdGuidance?` \`agentId\` targets: ${e.agentIdGuidance}`:``;return[n,e?.threadAvailable?'`mode="run"` one-shot; `mode="session"` persistent/thread-bound only on supporting requester channel.':'`mode="run"` one-shot background.',`\`agentId\` targets a configured agent; \`model\` overrides its model; \`cleanup\` delete|keep hidden child session; \`sandbox\` inherit|require.${r}`,"Execute work directly by default. Delegate a bounded, independent task only when parallel execution or an independent review provides a concrete benefit. Keep dependent steps with the same owner. Once delegation is appropriate, use a hidden subagent unless the user needs to revisit or steer deliberately supervised child work. This includes substantial, bounded API/service investigations that can be handed off with the needed context and capabilities. For hidden subagents, omit `visible` or set it false, and report results through the parent.","Native hidden or visible children support `worktree=true` with optional `projectId`, `worktreeName`, and `worktreeBaseRef`. Hidden `projectId` requires `worktree=true`; name/base always require it. Preparation is asynchronous; the first turn waits for the managed checkout. Hidden `cleanup=delete` uses session snapshot/removal; `keep` retains it. ACP does not support managed-worktree parameters. `group`, `projectGitUrl`, cloud profiles, and paired devices require `visible=true`.",'`visible=true`: durable visible supervised child session. Use when the user needs to revisit or steer delegated child work; an explicit request for a new independent session is not child delegation. Shows in web UI sidebar; works without UI: announcing runs report back, progress checkable. `group` places it in a custom sidebar group (a new name creates the group); omission or an empty string leaves it ungrouped. Subagent only; omit `mode` (`mode="run"` is also accepted), `thread`, `thinking`, and `lightContext`; `attachments=[]` and omitted/blank `attachAs.mountPath` are accepted, but nonempty attachment staging is unsupported; inherits the caller tool-policy ceiling except for configured deny-only `delegateToolsTo` grants (not tool arguments); select a registered project with `projectId` or a managed GitHub clone with `projectGitUrl` (mutually exclusive with each other and `cwd`); may check out a git worktree via `worktree`/`worktreeName`/`worktreeBaseRef`. When its accepted result includes `sessionUrl`, channel acknowledgements put the session URL on the first line and `Owner: <label>` on the second line.','Omit `placement` or use `{kind:"local"}` for local execution. `{kind:"profile",profileId,os?,machineClass?}` selects a configured cloud profile; `{kind:"device",deviceId}` selects one paired device by node ID. Both require `visible=true` and `worktree=true`. Placement creates first, dispatches, then starts the task; an unavailable or incompatible target fails, retains the child for inspection, and never falls back locally.',t,...e?.swarmEnabled?[SESSIONS_SPAWN_COLLECTOR_GUIDANCE]:[],"Inherits parent workspace. Native task arrives in the child's initial `[Subagent Task]` message.",...e?.acpAvailable===false||e?.agentIdGuidance?[]:['`runtime="acp"` ids: codex, claude, gemini, opencode, or configured ACP.'],describeSubagentSpawnContext(e?.subagentThreadAvailable===true),`A PR/report, long runtime, or isolated worktree alone does not justify a sidebar session. A request for a subagent does not request a separate session. No spawn for quick lookup/single read.`,`After spawn, do non-overlap work; follow the receipt's completion mode.`].join(` `)}function describeSessionStatusTool(){return[`Show visible-session model/usage/time/cost/tasks.`,'`sessionKey="current"` for current; UI labels are not keys.',"`model` overrides; `model=default` resets. Use for active model/session questions.","`capabilities=true` lists this session's available tools and why others are missing."].join(` `)}function describeRequiredHumanActionTool(e){return[`Use ${e} with requiredAction only for an observed external prerequisite, such as browser sign-in, that the human can complete while this run waits.`,`Do not invent approval or manual prerequisites for already authorized work. An inactive Goal stops automatic pursuit, not the current user-requested turn; continue executable work within its actual permissions without requiring Goal Resume. Never wait in ask_user for a native session control that requires this run to end; if that control is genuinely needed, explain it and finish the turn first.`,`Give the specific observed blocker and supported instructions; an optional verified URL opens separately from the completion answer. Reuse existing approval or native permission cards when available; never add another approval prompt, invent a remediation, request credentials in chat, or hide an incorrect denial.`,`requiredAction parks the original task and returns ready_to_verify, not success or authorization: re-observe the original target and continue from recorded progress only after the actual prerequisite is satisfied. action_unresolved means stop dependent work, report the blocker, and wait for a new user instruction; never use best-judgment fallback or repeat the handoff.`].join(` `)}function describeAskUserTool(){return["Ask the human user 1-3 structured questions and wait for their answer; `multiSelect` allows picking several options and `timeoutSeconds` bounds the wait.",`For questions, ask only about decisions genuinely theirs that cannot be resolved from the request, code, or sensible defaults; never ask whether to proceed or confirm a plan.`,describeRequiredHumanActionTool(`ask_user`),`Ask exactly one question per call unless several answers must be submitted together; one single-select question uses native controls on supported messaging channels.`,"Put every selectable choice in `options`, never only in the question text. Put the recommended option first and suffix its label with ` (Recommended)`.","Use `multiSelect` only when the user may choose several options at once; otherwise omit it.",`Do not include an Other option; free text is added automatically.`,`For ordinary questions only, no_answer means continue with best judgment.`].join(` `)}function describeSecretsTool(){return["Protected credentials: `list` metadata first; `request` missing task-needed name + reason via human masked entry; `delete` removes an entry.",`Request waits for human; value goes straight to shared store, never model/chat. Use the returned store SecretRef for supported config fields.`,`Gateway HTTPS egress only: enabled proxy + exact allowedHosts required; no hosts blocks egress, not config refs. No plaintext fallback.`,"Protected entries cannot supply SSH/sudo passwords or subprocess stdin; `${secret:NAME}` is not shell substitution. Check the supported consumer before requesting a credential.",SECRET_EGRESS_USAGE_PROMPT,`Operator-set env entries are readable and managed separately from this protected store. no_answer means no credential was supplied.`].join(` `)}
